  if (Buffer.isBuffer(b)) return b;
  if (b && typeof b === 'object' && b.type === 'Buffer' && Array.isArray(b.data)) return Buffer.from(b.data);
  if (typeof b === 'string') return Buffer.from(b);
  if (b && typeof b === 'object') return Buffer.from(JSON.stringify(b));
  return Buffer.from(String(b));
};
const __ra_toText = (b) => __ra_toBuf(b).toString('utf8');
const fetch = (url, opts = {}) => (async () => {
  try {
    const res = await __ra_helpers.httpRequest({
      method: (opts.method || 'GET').toUpperCase(),
      url,
      headers: opts.headers || {},
      body: opts.body,
      json: false,
      encoding: 'arraybuffer',
      returnFullResponse: true
    });
    return {
      ok: res.statusCode >= 200 && res.statusCode < 300,
      status: res.statusCode,
      json: async () => { const t = __ra_toText(res.body); try { return JSON.parse(t); } catch (e) { return t; } },
      text: async () => __ra_toText(res.body),
      arrayBuffer: async () => __ra_toBuf(res.body)
    };
  } catch (e) {
    return { ok: false, status: e.status || e.statusCode || 0, json: async () => ({}), text: async () => String(e.message || ''), arrayBuffer: async () => Buffer.alloc(0) };
  }
})();



const trigger = $('Execute Workflow Trigger').first().json.body;
const account = $('get_account_details').first().json;
const isBridge = account.bridge_enabled === true;
if (isBridge) {
  const msg = trigger.message || {};
  if (!msg.id) throw new Error('Bridge: datos de mensaje incompletos (pendiente forward completo de Yobot)');
  return { messages: [msg] };
}
const res = await fetch('https://api.mercadolibre.com' + trigger.resource + '?tag=post_sale', { headers: { Authorization: 'Bearer ' + account.access_token } });
if (!res.ok) throw new Error('ML message fetch: ' + res.status);
return await res.json();

const data = $input.first().json;
const msgs = data.messages || [];
const msg = [...msgs].reverse().find(m => m.status !== 'new') ?? msgs[msgs.length - 1];
if (!msg) throw new Error('No messages found in response');
const sellerId = String($('Execute Workflow Trigger').first().json.body.user_id);
const resources = msg.message_resources ?? [];
const packRes = resources.find(r => r.name === 'packs');
const orderRes = resources.find(r => r.name === 'orders');
// Fallback al pack_id del top-level del forward (Yobot lo manda siempre); ML no
// incluye message_resources en todos los mensajes.
const bodyPackId = $('Execute Workflow Trigger').first().json.body.pack_id;
const packId = packRes?.id ?? bodyPackId ?? null;
const orderId = orderRes?.id ?? packId;
return {
  id: msg.id,
  text: (msg.text ?? '').trim(),
  from: msg.from,
  to: msg.to,
  status: msg.status,
  message_type: String(msg.from?.user_id) === sellerId ? 'seller_to_buyer' : 'buyer_to_seller',
  pack_id: packId,
  order_id: orderId,
  conversation_status: data.conversation_status,
  attachments: msg.attachments || [],
  has_attachments: (msg.attachments || []).length > 0,
  message_resources: resources
};

const acct = $('get_account_details').first().json;
const msg  = $('normalize_message').first().json;
const API  = 'https://w1206-app.site';
const TOKEN = 'TSL8r4ctWYzXJF9fiAS1Z8RV';
const packId    = String(msg.pack_id || msg.order_id || '');
const inboxId   = String(acct.meli_inbox_id);
const accountId = acct.chatwoot_account_id;

const prev = $input.first().json;
const contactId = prev.payload?.contact?.id
                || prev.payload?.[0]?.id
                || prev.id;
if (!contactId) throw new Error('No contact_id: ' + JSON.stringify(prev));

async function apiGet(path) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: `${API}${path}`,
      headers: { api_access_token: TOKEN },
      returnFullResponse: false,
    });
    return r;
  } catch (e) {
    return null;
  }
}

async function apiPost(path, body) {
  return await this.helpers.httpRequest({
    method: 'POST',
    url: `${API}${path}`,
    headers: { api_access_token: TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

async function apiPostSafe(path, body) {
  try {
    return await apiPost.call(this, path, body);
  } catch (e) {
    return null;
  }
}

let existing = null;

// El search de contacto puede devolver un contacto duplicado (p. ej. el del bridge:
// identifier ml_buyer_<id>) que NO tiene la conversación post-venta. La conversación
// real puede existir bajo otro contacto con el mismo source_id (pack_id) del
// contact_inbox. Se resuelve el contacto dueño por source_id y se reusa su conversación.
async function findBySourceId() {
  if (!packId) return null;
  const owner = await apiPostSafe.call(this, `/api/v1/accounts/${accountId}/contact_inboxes/filter`, {
    inbox_id: Number(inboxId),
    source_id: packId
  });
  if (!owner || !owner.id) return null;
  const ownerData = await apiGet.call(this, `/api/v1/accounts/${accountId}/contacts/${owner.id}/conversations`);
  const ownerConvs = ownerData?.payload || [];
  return ownerConvs.find(c => {
    const attrs = c.additional_attributes || {};
    return (
      String(c.inbox_id) === inboxId &&
      (String(c.meta?.source_id) === packId ||
       String(attrs.pack_id) === packId ||
       String(attrs.order_id) === String(msg.order_id || ''))
    );
  }) || null;
}

const data = await apiGet.call(this, `/api/v1/accounts/${accountId}/contacts/${contactId}/conversations`);
const convs = data?.payload || [];
existing = convs.find(c => {
  const attrs = c.additional_attributes || {};
  return (
    String(c.inbox_id) === inboxId &&
    (String(c.meta?.source_id) === packId ||
     String(attrs.pack_id) === packId ||
     String(attrs.order_id) === String(msg.order_id || ''))
  );
});
if (!existing) {
  existing = await findBySourceId();
}

// La conversación post-venta puede existir bajo otro contacto (p. ej. creada por
// el setup manual del puente). La rescatamos por pack_id a nivel cuenta para no
// duplicar ni chocar con el source_id único de contact_inboxes.
const reusedFromDb = existing ? null : (acct.existing_pv_conversation_id || null);
if (reusedFromDb) {
  const got = await apiGet.call(this, `/api/v1/accounts/${accountId}/conversations/${reusedFromDb}`);
  if (got && got.id) {
    if (got.status === 'resolved' || got.status === 'snoozed') {
      await apiPost.call(this, `/api/v1/accounts/${accountId}/conversations/${got.id}/toggle_status`, { status: 'open' });
    }
    return { id: got.id, _reused: true, _from_db: true };
  }
}

if (existing) {
  if (existing.status === 'resolved' || existing.status === 'snoozed') {
    await apiPost.call(this, `/api/v1/accounts/${accountId}/conversations/${existing.id}/toggle_status`, { status: 'open' });
  }
  return { id: existing.id, _reused: true };
}

const created = await apiPost.call(this, `/api/v1/accounts/${accountId}/conversations`, {
  source_id:  packId,
  contact_id: contactId,
  inbox_id:   acct.meli_inbox_id,
  team_id:    acct.meli_team_id,
  status: 'open',
  additional_attributes: {
    type: 'post-venta',
    order_id: String(msg.order_id || ''),
    pack_id: packId
  }
});
return { id: created.id, _reused: false };

