const TIKA_URL = $env.TIKA_URL || 'http://tika:9998';
const OPENAI_KEY = $env.OPENAI_API_KEY || '';
const descs = [];

async function processBuffer(att, buf) {
  const mime = att.mime_type || att.type || '';
  try {
    if (mime.startsWith('image/')) {
      const r = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${OPENAI_KEY}` },
        body: JSON.stringify({
          model: $env.OPENAI_VISION_MODEL || 'gpt-4o-mini',
          messages: [{ role: 'user', content: [
            { type: 'text', text: 'Describí brevemente esta imagen enviada por un comprador en contexto post-venta (daño, falta de pieza, etc.).' },
            { type: 'image_url', image_url: { url: `data:${mime};base64,${buf.toString('base64')}` } }
          ] }],
          max_tokens: 200
        })
      });
      if (r.ok) { const j = await r.json(); descs.push(`Imagen: ${j.choices?.[0]?.message?.content || 'imagen recibida'}`); }
    } else if (mime === 'application/pdf' || mime.includes('pdf')) {
      const r = await fetch(`${TIKA_URL}/tika`, { method: 'PUT', body: buf, headers: { 'Content-Type': 'application/pdf' } });
      if (r.ok) { const t = await r.text(); descs.push(`PDF: ${t.slice(0, 1500)}`); }
    } else if (mime.startsWith('audio/')) {
      const form = new FormData();
      form.append('file', new Blob([buf], { type: mime }), `audio.${mime.split('/')[1] || 'mp3'}`);
      form.append('model', $env.OPENAI_WHISPER_MODEL || 'whisper-1');
      const r = await fetch('https://api.openai.com/v1/audio/transcriptions', {
        method: 'POST',
        headers: { Authorization: `Bearer ${OPENAI_KEY}` },
        body: form
      });
      if (r.ok) { const j = await r.json(); descs.push(`Audio (transcripción): ${j.text || ''}`); }
    } else {
      descs.push(`Adjunto recibido (${mime || 'desconocido'})`);
    }
  } catch (e) {
    descs.push('Adjunto recibido (no procesado)');
  }
}

// Bridge: los adjuntos vienen en el forward (URLs de message_attachments, sin token ML)
if (account.status === 'bridge' && account.bridge_enabled === true) {
  const fwd = $('Execute Workflow Trigger').first().json.body || {};
  const urls = Array.isArray(fwd.attachments) ? fwd.attachments : [];
  for (const att of urls) {
    try {
      const url = typeof att === 'string' ? att : (att.url || att.id);
      if (!url) continue;
      const res = await fetch(url);
      if (!res.ok) continue;
      const buf = Buffer.from(await res.arrayBuffer());
      await processBuffer(att, buf);
    } catch (e) { /* sigue con el siguiente adjunto */ }
  }
  return { ...$input.first().json, attachment_context: descs.length ? descs.join('\n') : '' };
}

